(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const msg=(selector,text)=>{const el=$(selector);if(el)el.textContent=text};
const download=(name,text,type='text/plain')=>{const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
document.querySelectorAll('[data-program-print]').forEach(b=>b.addEventListener('click',()=>window.print()));
const school=$('[data-school-checklist]');
if(school){const key='pcp-build-school-v1',boxes=[...school.querySelectorAll('input[type=checkbox]')],status=$('[data-school-status]');let saved=false;
 const paint=()=>status.textContent=boxes.filter(b=>b.checked).length+' of '+boxes.length+' checks marked. Marking a check is your confirmation, not a hardware certification.';
 try{const data=JSON.parse(localStorage.getItem(key)||'[]');boxes.forEach(b=>b.checked=Array.isArray(data)&&data.includes(b.value))}catch{}paint();
 const persist=()=>{try{localStorage.setItem(key,JSON.stringify(boxes.filter(b=>b.checked).map(b=>b.value)));saved=true}catch{saved=false}paint();if(!saved)status.textContent+=' This browser could not save progress.'};
 school.addEventListener('change',persist);$('[data-school-reset]')?.addEventListener('click',()=>{boxes.forEach(b=>b.checked=false);persist()});
 $('[data-school-export]')?.addEventListener('click',()=>{download('pc-build-checklist.txt','PC Part Performance build checklist\nhttps://www.pcpartperformance.com/build-school/\n\n'+boxes.map(b=>(b.checked?'[x] ':'[ ] ')+b.closest('label').textContent.trim()).join('\n'));window.PCP_EVENTS?.track('checklist_export',{page_type:'build_school'})});
}
const fit=$('[data-fit-form]');if(fit)fit.addEventListener('submit',e=>{e.preventDefault();const output=$('[data-fit-result]');try{const values=Object.fromEntries(new FormData(fit)),checks=PCP_PLANNERS.fit(values);output.innerHTML='<h2>Dimensional checks</h2><ul>'+checks.map(c=>`<li><strong class="program-state-${c.state}">${esc(c.title)}: ${esc(c.state.replaceAll('-',' '))}</strong><p>${esc(c.reason)} ${esc(c.remaining)}</p></li>`).join('')+'</ul><p>These results use your manual inputs. The 3D preview is not verified geometry.</p>';window.PCP_EVENTS?.track('compatibility_check_completed',{page_type:'compatibility'})}catch(err){output.textContent=err.message;output.setAttribute('role','alert')}});
const diagnostic=$('[data-diagnostic-form]');if(diagnostic){const show=()=>{const value=diagnostic.elements.symptom.value,entry=PCP_PLANNERS.diagnostics[value],out=$('[data-diagnostic-result]');if(!entry)return;out.innerHTML=`<h2>${esc(entry.title)}: your next checks</h2><ol>${entry.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><a href="${entry.next}">Continue with the relevant tool</a></p><p>Record the result of each change. Stop if a step requires a procedure you cannot verify in the exact manufacturer manual.</p>`;const url=new URL(location.href);url.searchParams.set('symptom',value);history.replaceState(null,'',url);window.PCP_EVENTS?.track('diagnostic_result_generated',{page_type:'troubleshooting',category:value})};diagnostic.addEventListener('submit',e=>{e.preventDefault();show()});const initial=new URLSearchParams(location.search).get('symptom');if(PCP_PLANNERS.diagnostics[initial]){diagnostic.elements.symptom.value=initial;show()}}
const display=$('[data-display-form]');if(display)display.addEventListener('submit',e=>{e.preventDefault();const out=$('[data-display-result]');try{const r=PCP_PLANNERS.display(Object.fromEntries(new FormData(display)));out.textContent=`Refresh interval: ${r.refreshInterval.toFixed(2)} ms.${r.frameInterval===null?' No observed FPS entered.':` Frame interval from your observed FPS: ${r.frameInterval.toFixed(2)} ms.`} ${r.limitation}`}catch(err){out.textContent=err.message;out.setAttribute('role','alert')}});
})();
